window.SEARCH_INDEX=[{"t": "Can a peaceful protest lead to detention?", "u": "article-peaceful-protest.html", "k": "Article", "d": "Peaceful assembly, restrictions and detention safeguards."}, {"t": "Freelancers and contracts: what should you check?", "u": "article-freelancer-contracts.html", "k": "Article", "d": "Scope, payment, ownership, confidentiality and disputes."}, {"t": "When can a social media post become evidence?", "u": "article-digital-evidence.html", "k": "Article", "d": "Electronic records, authenticity and context."}, {"t": "Maneka Gandhi v. Union of India, (1978) 1 SCC 248", "u": "case-law.html#case-maneka-gandhi-v-union-of-india", "k": "Case note", "d": "Constitutional. Fairness is part of Article 21, and arbitrary state action is open to challenge. How the principle works for a given statute still depends on its terms and the facts."}, {"t": "Shreya Singhal v. Union of India, (2015) 5 SCC 1", "u": "case-law.html#case-shreya-singhal-v-union-of-india", "k": "Case note", "d": "Constitutional. Vague criminal laws on speech can be struck down. Online expression receives constitutional protection, subject to restrictions that fit within Article 19(2)."}, {"t": "Justice K.S. Puttaswamy (Retd.) v. Union of India, (2017) 10 SCC 1", "u": "case-law.html#case-justice-k-s-puttaswamy-retd-v-union-of-india", "k": "Case note", "d": "Constitutional. Privacy is a fundamental right. The decision does not decide every privacy dispute, and later cases apply its tests to specific laws."}, {"t": "Kesavananda Bharati v. State of Kerala, (1973) 4 SCC 225", "u": "case-law.html#case-kesavananda-bharati-v-state-of-kerala", "k": "Case note", "d": "Constitutional. The basic structure doctrine. The list of basic features has been developed case by case since."}, {"t": "Minerva Mills Ltd. v. Union of India, (1980) 3 SCC 625", "u": "case-law.html#case-minerva-mills-ltd-v-union-of-india", "k": "Case note", "d": "Constitutional. Parliament cannot give itself unlimited amending power. Fundamental Rights and Directive Principles must be read in harmony."}, {"t": "S.R. Bommai v. Union of India, (1994) 3 SCC 1", "u": "case-law.html#case-s-r-bommai-v-union-of-india", "k": "Case note", "d": "Constitutional. Article 356 is a limited, reviewable power. Federalism and secularism are basic features of the Constitution."}, {"t": "Indra Sawhney v. Union of India, 1992 Supp (3) SCC 217", "u": "case-law.html#case-indra-sawhney-v-union-of-india", "k": "Case note", "d": "Constitutional. Sets the basic framework for OBC reservation. Later amendments and cases have addressed other questions, so check the current law."}, {"t": "Navtej Singh Johar v. Union of India, (2018) 10 SCC 1", "u": "case-law.html#case-navtej-singh-johar-v-union-of-india", "k": "Case note", "d": "Constitutional. Constitutional morality, not social morality, guides the Court. Consensual same-sex conduct between adults is not a crime."}, {"t": "Joseph Shine v. Union of India, (2019) 3 SCC 39", "u": "case-law.html#case-joseph-shine-v-union-of-india", "k": "Case note", "d": "Constitutional. Adultery is no longer a criminal offence. It can still be relevant in civil matters such as divorce."}, {"t": "Vishaka v. State of Rajasthan, (1997) 6 SCC 241", "u": "case-law.html#case-vishaka-v-state-of-rajasthan", "k": "Case note", "d": "Constitutional. Courts can fill a legislative gap. The guidelines were later replaced by the Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal) Act, 2013."}, {"t": "Olga Tellis v. Bombay Municipal Corporation, (1985) 3 SCC 545", "u": "case-law.html#case-olga-tellis-v-bombay-municipal-corporation", "k": "Case note", "d": "Constitutional. Livelihood is protected by Article 21. Eviction must follow a fair procedure, but the case does not create a right to occupy public land."}, {"t": "Bachan Singh v. State of Punjab, (1980) 2 SCC 684", "u": "case-law.html#case-bachan-singh-v-state-of-punjab", "k": "Case note", "d": "Criminal. Life imprisonment is the rule and death the exception, decided case by case. Later cases keep refining how the test is applied."}, {"t": "Lalita Kumari v. Government of Uttar Pradesh, (2014) 2 SCC 1", "u": "case-law.html#case-lalita-kumari-v-government-of-uttar-pradesh", "k": "Case note", "d": "Criminal. Police cannot refuse to register an FIR where a cognizable offence is disclosed. Section 154 CrPC is now Section 173 of the BNSS, so check the current text."}, {"t": "Arnesh Kumar v. State of Bihar, (2014) 8 SCC 273", "u": "case-law.html#case-arnesh-kumar-v-state-of-bihar", "k": "Case note", "d": "Criminal. Arrest needs recorded justification. The CrPC has since been replaced by the Bharatiya Nagarik Suraksha Sanhita, 2023, so check the corresponding provisions now in force."}, {"t": "Carlill v. Carbolic Smoke Ball Co., [1893] 1 QB 256", "u": "case-law.html#case-carlill-v-carbolic-smoke-ball-co", "k": "Case note", "d": "Contract. Leading case on unilateral offers and acceptance by performance. Section 8 of the Indian Contract Act, 1872 reflects the idea."}, {"t": "Mohori Bibee v. Dharmodas Ghose, (1903) ILR 30 Cal 539", "u": "case-law.html#case-mohori-bibee-v-dharmodas-ghose", "k": "Case note", "d": "Contract. A minor’s agreement is void in India. The case is a standard reference on capacity to contract."}, {"t": "Hadley v. Baxendale, (1854) 9 Exch 341", "u": "case-law.html#case-hadley-v-baxendale", "k": "Case note", "d": "Contract. Sets the remoteness rule for contract damages. Section 73 of the Indian Contract Act, 1872 follows a similar approach."}, {"t": "M.C. Mehta v. Union of India (Oleum Gas Leak), (1987) 1 SCC 395", "u": "case-law.html#case-m-c-mehta-v-union-of-india-oleum-gas-leak", "k": "Case note", "d": "Tort. India applies absolute liability for hazardous industries. It is a key case on environmental and industrial accidents."}, {"t": "Donoghue v. Stevenson, [1932] AC 562", "u": "case-law.html#case-donoghue-v-stevenson", "k": "Case note", "d": "Tort. Foundation of the modern law of negligence. Indian courts have referred to it when developing tort law."}, {"t": "Habeas Corpus", "u": "glossary.html#term-habeas-corpus", "k": "Glossary", "d": "Constitutional remedy. A writ used to require that a detained person be brought before a court so the legality of detention can be examined."}, {"t": "Mandamus", "u": "glossary.html#term-mandamus", "k": "Glossary", "d": "Constitutional remedy. A writ that directs a public authority to perform a public legal duty it has failed to perform. The word means “we command”."}, {"t": "Mens Rea", "u": "glossary.html#term-mens-rea", "k": "Glossary", "d": "Criminal law. Generally refers to the mental element of an offence. The required mental state depends on the particular offence and statute."}, {"t": "Cognizable Offence", "u": "glossary.html#term-cognizable-offence", "k": "Glossary", "d": "Criminal procedure. An offence for which the police can generally start an investigation and arrest without a warrant, as classified under the applicable procedural law."}, {"t": "Bail", "u": "glossary.html#term-bail", "k": "Glossary", "d": "Criminal procedure. The release of an accused person while a case is pending, usually on conditions. Rules and court discretion depend on the offence and the circumstances."}, {"t": "Prima Facie", "u": "glossary.html#term-prima-facie", "k": "Glossary", "d": "Evidence. Latin for “at first sight”. A prima facie case is one supported by enough evidence on its face to proceed unless it is rebutted."}, {"t": "Res Judicata", "u": "glossary.html#term-res-judicata", "k": "Glossary", "d": "Civil procedure. A principle that, subject to its legal requirements and exceptions, prevents a matter already finally decided between parties from being litigated again. In India, Section 11 of the Code of Civil Procedure, 1908 reflects it."}, {"t": "Locus Standi", "u": "glossary.html#term-locus-standi", "k": "Glossary", "d": "Procedure. The legal standing to bring a case. In public interest litigation, courts have relaxed this rule so that someone can approach the court for others."}, {"t": "Sub Judice", "u": "glossary.html#term-sub-judice", "k": "Glossary", "d": "Procedure. A matter that is under consideration by a court. Comments that could interfere with a pending case may raise legal concerns."}, {"t": "Ex Parte", "u": "glossary.html#term-ex-parte", "k": "Glossary", "d": "Procedure. A proceeding or order made in the absence of one of the parties, usually because they did not appear after proper notice."}, {"t": "Injunction", "u": "glossary.html#term-injunction", "k": "Glossary", "d": "Civil law. A court order requiring a party to do, or to stop doing, a specific act."}, {"t": "Indemnity", "u": "glossary.html#term-indemnity", "k": "Glossary", "d": "Contract law. A promise to compensate another person for loss. Section 124 of the Indian Contract Act, 1872 defines a contract of indemnity."}, {"t": "Stare Decisis", "u": "glossary.html#term-stare-decisis", "k": "Glossary", "d": "Precedent. The practice of following earlier decisions. In India, Article 141 makes the law declared by the Supreme Court binding on all courts."}, {"t": "Ratio Decidendi", "u": "glossary.html#term-ratio-decidendi", "k": "Glossary", "d": "Precedent. The legal principle on which a decision rests. This is the part of a judgment that carries precedential weight."}, {"t": "Obiter Dicta", "u": "glossary.html#term-obiter-dicta", "k": "Glossary", "d": "Precedent. Remarks in a judgment that were not necessary to decide the case. They can be persuasive but are not binding in the same way as the ratio."}, {"t": "Ultra Vires", "u": "glossary.html#term-ultra-vires", "k": "Glossary", "d": "Constitutional and administrative law. Latin for “beyond the powers”. An action or law that goes beyond the authority given by the Constitution or a statute can be challenged."}, {"t": "Murder: punishment: IPC 302 to BNS 103(1)", "u": "section-finder.html?q=IPC%20302", "k": "Section", "d": "BNS 103(2) adds a provision for murder by a group of five or more persons (mob lynching)."}, {"t": "Attempt to murder: IPC 307 to BNS 109", "u": "section-finder.html?q=IPC%20307", "k": "Section", "d": ""}, {"t": "Culpable homicide not amounting to murder: IPC 304 to BNS 105", "u": "section-finder.html?q=IPC%20304", "k": "Section", "d": ""}, {"t": "Death by negligence: IPC 304A to BNS 106(1)", "u": "section-finder.html?q=IPC%20304A", "k": "Section", "d": ""}, {"t": "Rape: definition: IPC 375 to BNS 63", "u": "section-finder.html?q=IPC%20375", "k": "Section", "d": ""}, {"t": "Rape: punishment: IPC 376 to BNS 64", "u": "section-finder.html?q=IPC%20376", "k": "Section", "d": ""}, {"t": "Dowry death: IPC 304B to BNS 80", "u": "section-finder.html?q=IPC%20304B", "k": "Section", "d": ""}, {"t": "Cruelty by husband or relatives: IPC 498A to BNS 85", "u": "section-finder.html?q=IPC%20498A", "k": "Section", "d": "The meaning of cruelty is now in BNS 86."}, {"t": "Assault to outrage the modesty of a woman: IPC 354 to BNS 74", "u": "section-finder.html?q=IPC%20354", "k": "Section", "d": ""}, {"t": "Sexual harassment: IPC 354A to BNS 75", "u": "section-finder.html?q=IPC%20354A", "k": "Section", "d": ""}, {"t": "Voluntarily causing hurt: IPC 323 to BNS 115(2)", "u": "section-finder.html?q=IPC%20323", "k": "Section", "d": ""}, {"t": "Criminal intimidation: IPC 503 / 506 to BNS 351", "u": "section-finder.html?q=IPC%20503", "k": "Section", "d": ""}, {"t": "Cheating and dishonestly inducing delivery of property: IPC 420 to BNS 318(4)", "u": "section-finder.html?q=IPC%20420", "k": "Section", "d": "Cheating provisions are grouped under BNS 318."}, {"t": "Theft: IPC 378 to BNS 303", "u": "section-finder.html?q=IPC%20378", "k": "Section", "d": "BNS 304 creates a separate offence of snatching."}, {"t": "Defamation: IPC 499 to BNS 356", "u": "section-finder.html?q=IPC%20499", "k": "Section", "d": ""}, {"t": "Common intention: IPC 34 to BNS 3(5)", "u": "section-finder.html?q=IPC%2034", "k": "Section", "d": ""}, {"t": "Criminal conspiracy: IPC 120A / 120B to BNS 61", "u": "section-finder.html?q=IPC%20120A", "k": "Section", "d": ""}, {"t": "Abetment: IPC 107 to BNS 45", "u": "section-finder.html?q=IPC%20107", "k": "Section", "d": ""}, {"t": "Attempt (general provision): IPC 511 to BNS 62", "u": "section-finder.html?q=IPC%20511", "k": "Section", "d": ""}, {"t": "Sedition: IPC 124A to Not carried forward", "u": "section-finder.html?q=IPC%20124A", "k": "Section", "d": "BNS 152 deals with acts endangering the sovereignty, unity and integrity of India. It is a different provision, not a renumbering."}, {"t": "Deceitful promise to marry: No IPC equivalent to BNS 69", "u": "section-finder.html?q=Deceitful%20promise%20to%20marry", "k": "Section", "d": "New specific offence."}, {"t": "Organised crime: No IPC equivalent to BNS 111", "u": "section-finder.html?q=Organised%20crime", "k": "Section", "d": "New offence."}, {"t": "Terrorist act: No IPC equivalent to BNS 113", "u": "section-finder.html?q=Terrorist%20act", "k": "Section", "d": "New offence in the BNS."}, {"t": "Arrest without warrant: CrPC 41 to BNSS 35", "u": "section-finder.html?q=CrPC%2041", "k": "Section", "d": ""}, {"t": "Notice of appearance before police: CrPC 41A to BNSS 35(3)", "u": "section-finder.html?q=CrPC%2041A", "k": "Section", "d": ""}, {"t": "How arrest is made: CrPC 46 to BNSS 43", "u": "section-finder.html?q=CrPC%2046", "k": "Section", "d": ""}, {"t": "Arrested person not to be detained over 24 hours without a magistrate: CrPC 57 to BNSS 58", "u": "section-finder.html?q=CrPC%2057", "k": "Section", "d": ""}, {"t": "Maintenance of wives, children and parents: CrPC 125 to BNSS 144", "u": "section-finder.html?q=CrPC%20125", "k": "Section", "d": ""}, {"t": "FIR: information in cognizable cases: CrPC 154 to BNSS 173", "u": "section-finder.html?q=CrPC%20154", "k": "Section", "d": "Provides for Zero FIR and electronic registration."}, {"t": "Power to require attendance of witnesses: CrPC 160 to BNSS 179", "u": "section-finder.html?q=CrPC%20160", "k": "Section", "d": ""}, {"t": "Examination of witnesses by police: CrPC 161 to BNSS 180", "u": "section-finder.html?q=CrPC%20161", "k": "Section", "d": ""}, {"t": "Recording of confessions before a magistrate: CrPC 164 to BNSS 183", "u": "section-finder.html?q=CrPC%20164", "k": "Section", "d": ""}, {"t": "Detention in custody; default bail: CrPC 167 to BNSS 187", "u": "section-finder.html?q=CrPC%20167", "k": "Section", "d": "Police custody can be spread across phases. The default bail right is preserved."}, {"t": "Police report on completion of investigation: CrPC 173 to BNSS 193", "u": "section-finder.html?q=CrPC%20173", "k": "Section", "d": ""}, {"t": "Cognizance of offences by magistrates: CrPC 190 to BNSS 210", "u": "section-finder.html?q=CrPC%20190", "k": "Section", "d": ""}, {"t": "Examination of complainant: CrPC 200 to BNSS 223", "u": "section-finder.html?q=CrPC%20200", "k": "Section", "d": ""}, {"t": "Summary trials: CrPC 260 to BNSS 283", "u": "section-finder.html?q=CrPC%20260", "k": "Section", "d": ""}, {"t": "Compounding of offences: CrPC 320 to BNSS 359", "u": "section-finder.html?q=CrPC%20320", "k": "Section", "d": ""}, {"t": "Judgment: CrPC 353 to BNSS 392", "u": "section-finder.html?q=CrPC%20353", "k": "Section", "d": ""}, {"t": "Appeal against conviction: CrPC 374 to BNSS 415", "u": "section-finder.html?q=CrPC%20374", "k": "Section", "d": ""}, {"t": "Anticipatory bail: CrPC 438 to BNSS 482", "u": "section-finder.html?q=CrPC%20438", "k": "Section", "d": "BNSS 482 now means anticipatory bail, not inherent powers."}, {"t": "Bail: High Court or Court of Session: CrPC 439 to BNSS 483", "u": "section-finder.html?q=CrPC%20439", "k": "Section", "d": ""}, {"t": "Maximum detention of undertrial prisoners: CrPC 436A to BNSS 479", "u": "section-finder.html?q=CrPC%20436A", "k": "Section", "d": ""}, {"t": "Inherent powers of the High Court: CrPC 482 to BNSS 528", "u": "section-finder.html?q=CrPC%20482", "k": "Section", "d": "Section 482 changed meaning. Do not cite the old number."}, {"t": "Bail in non-bailable offences (Magistrate): CrPC 437 to BNSS 480", "u": "section-finder.html?q=CrPC%20437", "k": "Section", "d": ""}, {"t": "Interpretation clause (definitions): Evidence Act 3 to BSA 2", "u": "section-finder.html?q=Evidence%20Act%203", "k": "Section", "d": ""}, {"t": "Confession to a police officer: Evidence Act 25, 26 to BSA 23(1)", "u": "section-finder.html?q=Evidence%20Act%2025%2C%2026", "k": "Section", "d": "Consolidated in BSA 23 with the discovery provision."}, {"t": "Information leading to discovery: Evidence Act 27 to BSA 23(2)", "u": "section-finder.html?q=Evidence%20Act%2027", "k": "Section", "d": ""}, {"t": "Opinion of experts: Evidence Act 45 to BSA 39", "u": "section-finder.html?q=Evidence%20Act%2045", "k": "Section", "d": ""}, {"t": "Primary evidence: Evidence Act 62 to BSA 57", "u": "section-finder.html?q=Evidence%20Act%2062", "k": "Section", "d": ""}, {"t": "Secondary evidence: Evidence Act 63 to BSA 58", "u": "section-finder.html?q=Evidence%20Act%2063", "k": "Section", "d": ""}, {"t": "Admissibility of electronic records: Evidence Act 65B to BSA 63", "u": "section-finder.html?q=Evidence%20Act%2065B", "k": "Section", "d": "BSA 63 includes a certificate format in a Schedule. Check recent court rulings on its use."}, {"t": "Burden of proving a fact especially within knowledge: Evidence Act 106 to BSA 106", "u": "section-finder.html?q=Evidence%20Act%20106", "k": "Section", "d": "Same number."}, {"t": "Article 12: Definition of “State”", "u": "constitution.html?q=Article%2012", "k": "Constitution", "d": "For Part III, “the State” includes the Government and Parliament, state governments and legislatures, and local and other authorities."}, {"t": "Article 13: Laws inconsistent with Fundamental Rights", "u": "constitution.html?q=Article%2013", "k": "Constitution", "d": "Laws that conflict with Fundamental Rights are void to the extent of the inconsistency."}, {"t": "Article 14: Equality before law", "u": "constitution.html?q=Article%2014", "k": "Constitution", "d": "The State shall not deny any person equality before the law or the equal protection of the laws."}, {"t": "Article 15: Prohibition of discrimination", "u": "constitution.html?q=Article%2015", "k": "Constitution", "d": "No discrimination on grounds only of religion, race, caste, sex or place of birth. Special provisions for women, children and backward classes are permitted."}, {"t": "Article 16: Equality of opportunity in public employment", "u": "constitution.html?q=Article%2016", "k": "Constitution", "d": "Equal opportunity in public jobs, with provision for reservation for backward classes not adequately represented."}, {"t": "Article 17: Abolition of untouchability", "u": "constitution.html?q=Article%2017", "k": "Constitution", "d": "Untouchability is abolished and its practice in any form is forbidden."}, {"t": "Article 18: Abolition of titles", "u": "constitution.html?q=Article%2018", "k": "Constitution", "d": "The State cannot confer titles, apart from military or academic distinctions."}, {"t": "Article 19: Protection of certain freedoms", "u": "constitution.html?q=Article%2019", "k": "Constitution", "d": "Citizens have the freedoms of speech and expression, peaceful assembly, association, movement, residence and practising a profession or business, subject to reasonable restrictions."}, {"t": "Article 20: Protection in respect of conviction for offences", "u": "constitution.html?q=Article%2020", "k": "Constitution", "d": "No retrospective criminal laws, no double jeopardy, and no compulsion to be a witness against oneself."}, {"t": "Article 21: Protection of life and personal liberty", "u": "constitution.html?q=Article%2021", "k": "Constitution", "d": "No person shall be deprived of life or personal liberty except according to procedure established by law. Courts have read in fairness, privacy, livelihood and more."}, {"t": "Article 21A: Right to education", "u": "constitution.html?q=Article%2021A", "k": "Constitution", "d": "Free and compulsory education for children aged six to fourteen."}, {"t": "Article 22: Protection against arrest and detention", "u": "constitution.html?q=Article%2022", "k": "Constitution", "d": "Rights to be told the grounds of arrest, to consult a lawyer, and to be produced before a magistrate within 24 hours. Special rules apply to preventive detention."}, {"t": "Article 23: Prohibition of trafficking and forced labour", "u": "constitution.html?q=Article%2023", "k": "Constitution", "d": "Traffic in human beings and forced labour are prohibited."}, {"t": "Article 24: Prohibition of employment of children", "u": "constitution.html?q=Article%2024", "k": "Constitution", "d": "No child below fourteen may be employed in a factory, mine or other hazardous work."}, {"t": "Article 25: Freedom of religion", "u": "constitution.html?q=Article%2025", "k": "Constitution", "d": "Freedom of conscience and the right to profess, practise and propagate religion, subject to public order, morality and health."}, {"t": "Article 26: Freedom to manage religious affairs", "u": "constitution.html?q=Article%2026", "k": "Constitution", "d": "Religious denominations may manage their own religious affairs and institutions, subject to public order, morality and health."}, {"t": "Article 27: Freedom from taxes for religion", "u": "constitution.html?q=Article%2027", "k": "Constitution", "d": "No one can be compelled to pay taxes for promoting a particular religion."}, {"t": "Article 28: Freedom in religious instruction", "u": "constitution.html?q=Article%2028", "k": "Constitution", "d": "Limits on religious instruction in State-funded educational institutions."}, {"t": "Article 29: Protection of minorities’ interests", "u": "constitution.html?q=Article%2029", "k": "Constitution", "d": "Any section of citizens with a distinct language, script or culture has the right to conserve it."}, {"t": "Article 30: Minorities’ right to educational institutions", "u": "constitution.html?q=Article%2030", "k": "Constitution", "d": "Minorities have the right to establish and administer educational institutions of their choice."}, {"t": "Article 32: Right to constitutional remedies", "u": "constitution.html?q=Article%2032", "k": "Constitution", "d": "The right to move the Supreme Court to enforce Fundamental Rights, including through writs."}, {"t": "Article 36: Definition of “State” in Part IV", "u": "constitution.html?q=Article%2036", "k": "Constitution", "d": "Has the same meaning as in Part III unless the context requires otherwise."}, {"t": "Article 37: Application of Directive Principles", "u": "constitution.html?q=Article%2037", "k": "Constitution", "d": "Directive Principles are not enforceable by courts, but are fundamental in governing the country."}, {"t": "Article 39A: Equal justice and free legal aid", "u": "constitution.html?q=Article%2039A", "k": "Constitution", "d": "The State shall ensure that the legal system promotes justice on the basis of equal opportunity, including free legal aid."}, {"t": "Article 44: Uniform civil code", "u": "constitution.html?q=Article%2044", "k": "Constitution", "d": "The State shall endeavour to secure a uniform civil code for citizens throughout India."}, {"t": "Article 48A: Protection of the environment", "u": "constitution.html?q=Article%2048A", "k": "Constitution", "d": "The State shall endeavour to protect and improve the environment and safeguard forests and wildlife."}, {"t": "Article 50: Separation of judiciary from executive", "u": "constitution.html?q=Article%2050", "k": "Constitution", "d": "The State shall take steps to separate the judiciary from the executive in public services."}, {"t": "Article 51A: Fundamental Duties", "u": "constitution.html?q=Article%2051A", "k": "Constitution", "d": "A list of duties of every citizen, such as respecting the Constitution, protecting the environment and developing scientific temper."}, {"t": "Article 52: The President of India", "u": "constitution.html?q=Article%2052", "k": "Constitution", "d": "There shall be a President of India."}, {"t": "Article 53: Executive power of the Union", "u": "constitution.html?q=Article%2053", "k": "Constitution", "d": "The executive power of the Union is vested in the President."}, {"t": "Article 72: Power of the President to grant pardons", "u": "constitution.html?q=Article%2072", "k": "Constitution", "d": "The President may grant pardons, reprieves, respites or remissions of punishment and suspend, remit or commute sentences in specified cases."}, {"t": "Article 74: Council of Ministers to aid and advise President", "u": "constitution.html?q=Article%2074", "k": "Constitution", "d": "There shall be a Council of Ministers with the Prime Minister at the head to aid and advise the President."}, {"t": "Article 79: Constitution of Parliament", "u": "constitution.html?q=Article%2079", "k": "Constitution", "d": "Parliament consists of the President and the two Houses: the Council of States and the House of the People."}, {"t": "Article 123: Power of the President to promulgate ordinances", "u": "constitution.html?q=Article%20123", "k": "Constitution", "d": "The President can issue ordinances when Parliament is not in session, if circumstances require immediate action."}, {"t": "Article 124: Establishment of the Supreme Court", "u": "constitution.html?q=Article%20124", "k": "Constitution", "d": "Provides for the Supreme Court of India and its judges."}, {"t": "Article 129: Supreme Court as a court of record", "u": "constitution.html?q=Article%20129", "k": "Constitution", "d": "The Supreme Court is a court of record with power to punish for contempt of itself."}, {"t": "Article 131: Original jurisdiction of the Supreme Court", "u": "constitution.html?q=Article%20131", "k": "Constitution", "d": "The Supreme Court decides certain disputes between the Union and States, or between States, in its original jurisdiction."}, {"t": "Article 136: Special leave to appeal", "u": "constitution.html?q=Article%20136", "k": "Constitution", "d": "The Supreme Court may grant special leave to appeal from almost any court or tribunal in India."}, {"t": "Article 141: Law declared by the Supreme Court", "u": "constitution.html?q=Article%20141", "k": "Constitution", "d": "The law declared by the Supreme Court is binding on all courts in India."}, {"t": "Article 142: Enforcement of decrees and orders", "u": "constitution.html?q=Article%20142", "k": "Constitution", "d": "The Supreme Court can pass such orders as are necessary to do complete justice in a case."}, {"t": "Article 143: Power of the President to consult the Supreme Court", "u": "constitution.html?q=Article%20143", "k": "Constitution", "d": "The President may seek the Supreme Court’s advisory opinion on a question of law or fact."}, {"t": "Article 161: Power of the Governor to grant pardons", "u": "constitution.html?q=Article%20161", "k": "Constitution", "d": "The Governor may grant pardons and similar relief in matters within the State’s executive power."}, {"t": "Article 213: Power of the Governor to promulgate ordinances", "u": "constitution.html?q=Article%20213", "k": "Constitution", "d": "The Governor can issue ordinances when the State Legislature is not in session."}, {"t": "Article 214: High Courts for States", "u": "constitution.html?q=Article%20214", "k": "Constitution", "d": "There shall be a High Court for each State."}, {"t": "Article 215: High Courts as courts of record", "u": "constitution.html?q=Article%20215", "k": "Constitution", "d": "High Courts are courts of record and can punish for contempt of themselves."}, {"t": "Article 226: Power of High Courts to issue writs", "u": "constitution.html?q=Article%20226", "k": "Constitution", "d": "High Courts can issue writs to enforce Fundamental Rights and for any other purpose."}, {"t": "Article 227: Superintendence over courts", "u": "constitution.html?q=Article%20227", "k": "Constitution", "d": "Every High Court has superintendence over all courts and tribunals in its territory."}, {"t": "Article 245: Extent of laws made by Parliament and States", "u": "constitution.html?q=Article%20245", "k": "Constitution", "d": "Parliament and State Legislatures make laws for their territories, subject to the Constitution."}, {"t": "Article 246: Subject-matter of laws", "u": "constitution.html?q=Article%20246", "k": "Constitution", "d": "Divides legislative subjects among the Union, State and Concurrent Lists in the Seventh Schedule."}, {"t": "Article 300A: Persons not to be deprived of property save by law", "u": "constitution.html?q=Article%20300A", "k": "Constitution", "d": "No person shall be deprived of property except by authority of law. This is a constitutional right, not a Fundamental Right."}, {"t": "Article 324: Election Commission", "u": "constitution.html?q=Article%20324", "k": "Constitution", "d": "Superintendence, direction and control of elections is vested in the Election Commission."}, {"t": "Article 326: Adult suffrage", "u": "constitution.html?q=Article%20326", "k": "Constitution", "d": "Elections to the House of the People and State Assemblies are on the basis of adult suffrage."}, {"t": "Article 352: Proclamation of Emergency", "u": "constitution.html?q=Article%20352", "k": "Constitution", "d": "The President can proclaim an Emergency on grounds such as war, external aggression or armed rebellion, subject to conditions."}, {"t": "Article 356: Failure of constitutional machinery in States", "u": "constitution.html?q=Article%20356", "k": "Constitution", "d": "Provides for President’s Rule in a State. The power is subject to judicial review (S.R. Bommai)."}, {"t": "Article 360: Financial Emergency", "u": "constitution.html?q=Article%20360", "k": "Constitution", "d": "Provides for a Financial Emergency if the financial stability or credit of India is threatened."}, {"t": "Article 368: Power of Parliament to amend the Constitution", "u": "constitution.html?q=Article%20368", "k": "Constitution", "d": "Parliament may amend the Constitution, but not its basic structure (Kesavananda Bharati)."}, {"t": "Old-to-new section finder", "u": "section-finder.html", "k": "Guide", "d": "IPC to BNS, CrPC to BNSS, Evidence Act to BSA"}, {"t": "Quiz bank", "u": "quiz.html", "k": "Guide", "d": "Subject-wise law quizzes"}, {"t": "Moot court corner", "u": "moot.html", "k": "Guide", "d": "Memorials, issues and oral advocacy"}, {"t": "Drafting practice", "u": "drafting.html", "k": "Guide", "d": "Legal notice, petition, RTI, contract clauses"}, {"t": "Careers and internships", "u": "careers.html", "k": "Guide", "d": "Internships, CV, interviews"}, {"t": "Know your rights", "u": "know-your-rights.html", "k": "Guide", "d": "Arrest, FIR, consumer complaint, legal aid"}, {"t": "Law exam hub", "u": "exam-hub.html", "k": "Guide", "d": "CLAT, AIBE, judicial services, UGC-NET"}, {"t": "Citation generator", "u": "cite-it.html", "k": "Guide", "d": "Format case and statute citations"}, {"t": "Browse by topic", "u": "topics.html", "k": "Guide", "d": "All content by area of law"}, {"t": "Decision Room", "u": "decision-room.html", "k": "Guide", "d": "Scenario practice"}, {"t": "About Legal Lounge Live", "u": "about.html", "k": "Guide", "d": "Mission and editorial standards"}];